import{IsoScene}from'/viewer/iso-scene.js';
import{TownScene}from'/viewer/scene.js';
import{inspectSnapshot}from'/viewer/adapter.js';
const $=id=>document.getElementById(id),id=new URL(location.href).searchParams.get('id');
let world,town,scene,mode='iso',selected=null,generation=0,selection=0,observations=null,busy=false;
const layers=()=>Object.fromEntries(['electric','water','gas'].map(k=>[k,$(k).checked]));
async function request(action,params={}){const r=await fetch('/api/compute?'+new URLSearchParams({action,id,...params}),{cache:'no-store',credentials:'same-origin'});const v=await r.json();if(!r.ok)throw Error(v.detail||v.error||'Saved world unavailable.');return v;}
function notice(text){$('status').textContent=text;}
function controls(){for(const key of ['iso','three','fit','zoom-in','zoom-out','rotate','inspect','refresh'])$(key).disabled=busy||!town;}
function renderScene(next){scene?.destroy();scene=null;mode=next;const callback=value=>{if(value.home)void inspect(value.home.id,false);else if(value.asset){$('detail-status').textContent='Saved '+value.asset+' network equipment: '+value.nodeId;}else if(value.landmark){$('detail-status').textContent=value.landmark.label+' · saved physical facility';}};
 try{scene=next==='iso'?new IsoScene($('city-scene'),callback,'full'):new TownScene($('city-scene'),callback,'full',{renderOnDemand:true});scene.load(town,{demo:false});scene.play=false;scene.setLayers(layers());scene.setClock({sunElevationDeg:45,sunAzimuthDeg:135});if(selected)scene.select(town.premises.find(h=>h.id===selected),'electric',false);
 $('iso').setAttribute('aria-pressed',String(next==='iso'));$('three').setAttribute('aria-pressed',String(next==='3d'));$('rotate').hidden=next==='3d';$('hint').textContent=next==='iso'?'Drag to pan · scroll to zoom · Rotate changes viewpoint · click a building':'Drag to pan · scroll to zoom · right-drag to orbit · click a building';$('city-scene').dataset.mode=next;
 if(next==='iso')scene.ready.then(ok=>{if(!ok)notice('Isometric artwork could not load. Try 3D or refresh.');});
 const url=new URL(location.href);url.searchParams.set('view',next);history.replaceState(null,'',url);
 }catch(error){scene?.destroy();scene=null;throw error;}}
function details(value){$('details').replaceChildren();for(const[k,label]of [['premiseId','Premise'],['address','Address'],['parcelId','Parcel'],['type','Type'],['occupied','Occupied']])if(value[k]!==undefined){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=String(value[k]);$('details').append(dt,dd);}}
function readings(premiseId){const root=$('readings');root.replaceChildren();if(!observations){root.textContent=world.days?'Recorded observations are unavailable.':'No days have been committed yet.';return;}const meters=new Set(observations.assets.filter(a=>a.premiseId===premiseId).map(a=>a.meterId)),rows=observations.observations.filter(o=>meters.has(o.meterId));if(!rows.length){root.textContent='No observations collected for this property in the latest committed day.';return;}for(const o of rows){const row=document.createElement('div');row.className='reading';const title=document.createElement('strong'),date=document.createElement('small');title.textContent=`${o.commodity}: ${o.quantity??'Unknown'} ${o.unit} · ${o.status}`;date.textContent=`${o.start} → ${o.end} · ${o.meterId}`;row.append(title,date);root.append(row);}}
async function inspect(premiseId,focus){if(!town||!town.premises.some(h=>h.id===premiseId))return;const version=++selection,worldVersion=generation;selected=premiseId;$('premise').value=premiseId;$('details').replaceChildren();$('vs').hidden=true;$('detail-status').textContent='Reading the current saved property…';scene?.select(town.premises.find(h=>h.id===premiseId),'electric',focus);try{const value=await request('premise',{premiseId});if(version!==selection||worldVersion!==generation)return;if(value.worldId!==world.id||value.sourceRevision!==world.sourceRevision||value.premise?.premiseId!==premiseId)throw Error('The selected property was not confirmed.');details(value.premise);readings(premiseId);$('detail-status').textContent='Current owned-world property confirmed.';if(world.connectedClock?.configured){$('vs').href='/vs-operator.html?'+new URLSearchParams({id,premiseId});$('vs').hidden=false;}}catch(error){if(version===selection)$('detail-status').textContent=error.message;}}
async function load(){if(busy)return;busy=true;generation++;selection++;controls();notice('Reading your saved world…');try{if(!/^[a-f0-9]{32}$/.test(id||''))throw Error('Open a saved simulation from your workspace.');world=await request('status');const city=await request('city');if(city.worldId!==world.id||city.sourceRevision!==world.sourceRevision)throw Error('City does not match the selected world.');inspectSnapshot(city.geometry);town=city.geometry;observations=null;selected=null;$('details').replaceChildren();$('readings').textContent='Select a property.';$('vs').hidden=true;$('name').textContent=world.name;$('clock').textContent='Saved UTC cursor: '+world.through;$('world-controls').href='/world-control.html?id='+id;$('art').href='/world-control.html?id='+id;$('premise').replaceChildren();for(const h of [...town.premises].sort((a,b)=>(a.address||a.id).localeCompare(b.address||b.id))){const o=document.createElement('option');o.value=h.id;o.textContent=h.address||h.id;$('premise').append(o);}renderScene(new URL(location.href).searchParams.get('view')==='3d'?'3d':'iso');
 if(world.days>0){const end=world.through,start=new Date(Date.parse(end+'T00:00:00Z')-86400000).toISOString().slice(0,10);try{observations=await request('observations',{start,end});if(observations.environmentId!==world.environmentId)throw Error('Observation world mismatch.');}catch{observations=null;}}
 notice(`${town.premises.length} properties · saved geometry and records · ${world.days} committed days`);
 }catch(error){notice(error.message);}finally{busy=false;controls();}}
$('iso').onclick=()=>{try{renderScene('iso');}catch(e){notice(e.message);}};$('three').onclick=()=>{try{renderScene('3d');}catch(e){notice(e.message);}};$('fit').onclick=()=>scene?.home();$('zoom-in').onclick=()=>scene?.zoom(.75);$('zoom-out').onclick=()=>scene?.zoom(1/.75);$('rotate').onclick=()=>scene?.rotate();$('inspect').onclick=()=>inspect($('premise').value,true);$('refresh').onclick=load;for(const key of ['electric','water','gas'])$(key).onchange=()=>scene?.setLayers(layers());window.addEventListener('pagehide',()=>scene?.destroy());void load();
